vector<int> findAnagrams(string s, string p) {
    int cnt[26] = {}; for (char c : p) cnt[c-'a']++;
    vector<int> ans;
    int need = p.size();
    for (int r = 0; r < s.size(); r++) {
        if (cnt[s[r]-'a']-- > 0) need--;              // useful char consumed
        int l = r - (int)p.size();
        if (l >= 0 && cnt[s[l]-'a']++ >= 0) need++;   // returned char restores
        if (need == 0) ans.push_back(l + 1);
    }
    return ans;
}

