from collections import Counter
def find_anagrams(s, p):
    need = Counter(p); need_cnt = len(p)
    ans = []
    for r, c in enumerate(s):
        if need[c] > 0: need_cnt -= 1
        need[c] -= 1
        l = r - len(p)
        if l >= 0:
            if need[s[l]] >= 0: need_cnt += 1
            need[s[l]] += 1
        if need_cnt == 0: ans.append(l + 1)
    return ans

